class Solution {
    int find(vector<int>& p, int x) {
        while (p[x] != x) { p[x] = p[p[x]]; x = p[x]; }
        return x;
    }
public:
    int minimumVisitedCells(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> rowP(m, vector<int>(n + 1)), colP(n, vector<int>(m + 1));
        for (int i = 0; i < m; i++) for (int c = 0; c <= n; c++) rowP[i][c] = c;
        for (int j = 0; j < n; j++) for (int r = 0; r <= m; r++) colP[j][r] = r;
        vector<vector<int>> dist(m, vector<int>(n, -1));
        queue<pair<int,int>> dq;
        dist[0][0] = 1; dq.push({0, 0});
        while (!dq.empty()) {
            auto [i, j] = dq.front(); dq.pop();
            if (i == m - 1 && j == n - 1) return dist[i][j];
            int g = grid[i][j];
            for (int x = find(rowP[i], j + 1); x <= min(j + g, n - 1); ) {
                dist[i][x] = dist[i][j] + 1; dq.push({i, x});
                rowP[i][x] = x + 1;
                x = find(rowP[i], x + 1);
            }
            for (int y = find(colP[j], i + 1); y <= min(i + g, m - 1); ) {
                if (dist[y][j] == -1) { dist[y][j] = dist[i][j] + 1; dq.push({y, j}); }
                colP[j][y] = y + 1;
                y = find(colP[j], y + 1);
            }
        }
        return -1;
    }
};

