import java.util.*;
class Solution {
    private int find(int[] p, int x) {
        while (p[x] != x) { p[x] = p[p[x]]; x = p[x]; }
        return x;
    }
    public int minimumVisitedCells(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][] rowP = new int[m][n + 1], colP = new int[n][m + 1];
        for (int i = 0; i < m; i++) for (int c = 0; c <= n; c++) rowP[i][c] = c;
        for (int j = 0; j < n; j++) for (int r = 0; r <= m; r++) colP[j][r] = r;
        int[][] dist = new int[m][n];
        for (int[] r : dist) Arrays.fill(r, -1);
        Deque<int[]> dq = new ArrayDeque<>();
        dist[0][0] = 1; dq.add(new int[]{0, 0});
        while (!dq.isEmpty()) {
            int[] cur = dq.poll(); int i = cur[0], j = cur[1];
            if (i == m - 1 && j == n - 1) return dist[i][j];
            int g = grid[i][j];
            for (int x = find(rowP[i], j + 1); x <= Math.min(j + g, n - 1); ) {
                dist[i][x] = dist[i][j] + 1; dq.add(new int[]{i, x});
                rowP[i][x] = x + 1;
                x = find(rowP[i], x + 1);
            }
            for (int y = find(colP[j], i + 1); y <= Math.min(i + g, m - 1); ) {
                if (dist[y][j] == -1) { dist[y][j] = dist[i][j] + 1; dq.add(new int[]{y, j}); }
                colP[j][y] = y + 1;
                y = find(colP[j], y + 1);
            }
        }
        return -1;
    }
}

