// C++ has no built-in sorted list; emulate with per-row/per-column std::set.
class Solution {
public:
    int minimumVisitedCells(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<set<int>> rows(m), cols(n);
        for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) { rows[i].insert(j); cols[j].insert(i); }
        vector<vector<int>> dist(m, vector<int>(n, -1));
        queue<pair<int,int>> dq;
        dist[0][0] = 1; dq.push({0, 0});
        while (!dq.empty()) {
            auto [i, j] = dq.front(); dq.pop();
            if (i == m - 1 && j == n - 1) return dist[i][j];
            int g = grid[i][j];
            for (auto it = rows[i].upper_bound(j); it != rows[i].end() && *it <= min(j + g, n - 1); it = rows[i].erase(it)) {
                cols[*it].erase(i);
                dist[i][*it] = dist[i][j] + 1; dq.push({i, *it});
            }
            for (auto it = cols[j].upper_bound(i); it != cols[j].end() && *it <= min(i + g, m - 1); it = cols[j].erase(it)) {
                rows[*it].erase(j);
                dist[*it][j] = dist[i][j] + 1; dq.push({*it, j});
            }
        }
        return -1;
    }
};

