// Java: TreeSet per row/column, same pattern as the C++ set version.
class Solution {
    public int minimumVisitedCells(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        TreeSet<Integer>[] rows = new TreeSet[m], cols = new TreeSet[n];
        for (int i = 0; i < m; i++) { rows[i] = new TreeSet<>(); for (int j = 0; j < n; j++) rows[i].add(j); }
        for (int j = 0; j < n; j++) { cols[j] = new TreeSet<>(); for (int i = 0; i < m; i++) cols[j].add(i); }
        int[][] dist = new int[m][n];
        for (int[] r : dist) Arrays.fill(r, -1);
        Deque<int[]> dq = new ArrayDeque<>();
        dist[0][0] = 1; dq.add(new int[]{0, 0});
        while (!dq.isEmpty()) {
            int[] cur = dq.poll(); int i = cur[0], j = cur[1];
            if (i == m - 1 && j == n - 1) return dist[i][j];
            int g = grid[i][j];
            for (Integer x : new ArrayList<>(rows[i].subSet(j + 1, true, Math.min(j + g, n - 1), true))) {
                rows[i].remove(x); cols[x].remove(i);
                dist[i][x] = dist[i][j] + 1; dq.add(new int[]{i, x});
            }
            for (Integer y : new ArrayList<>(cols[j].subSet(i + 1, true, Math.min(i + g, m - 1), true))) {
                cols[j].remove(y); rows[y].remove(j);
                dist[y][j] = dist[i][j] + 1; dq.add(new int[]{y, j});
            }
        }
        return -1;
    }
}

