// JS: emulate sorted sets with arrays kept sorted (acceptable at these sizes).
var minimumVisitedCells = function(grid) {
    const m = grid.length, n = grid[0].length;
    const rows = Array.from({length: m}, (_, i) => Array.from({length: n}, (_, j) => j));
    const cols = Array.from({length: n}, (_, j) => Array.from({length: m}, (_, i) => i));
    const dist = Array.from({length: m}, () => new Array(n).fill(-1));
    dist[0][0] = 1;
    const dq = [[0, 0]];
    for (let h = 0; h < dq.length; h++) {
        const [i, j] = dq[h];
        if (i === m - 1 && j === n - 1) return dist[i][j];
        const g = grid[i][j];
        const take = (arr, lo, hi, cb) => {
            const keep = [];
            for (const v of arr) (v >= lo && v <= hi) ? cb(v) : keep.push(v);
            arr.length = 0; arr.push(...keep);
        };
        take(rows[i], j + 1, Math.min(j + g, n - 1), x => {
            const ci = cols[x].indexOf(i); if (ci >= 0) cols[x].splice(ci, 1);
            dist[i][x] = dist[i][j] + 1; dq.push([i, x]);
        });
        take(cols[j], i + 1, Math.min(i + g, m - 1), y => {
            const ri = rows[y].indexOf(j); if (ri >= 0) rows[y].splice(ri, 1);
            dist[y][j] = dist[i][j] + 1; dq.push([y, j]);
        });
    }
    return -1;
};
